how.python:
def bubble_sort(a):
    n = len(a)
    for i in range(n - 1, 0, -1):
        swapped = False
        for j in range(i):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                swapped = True
        if not swapped:
            break
    return a


def selection_sort(a):
    n = len(a)
    for i in range(n - 1):
        k = i
        for j in range(i + 1, n):
            if a[j] < a[k]:
                k = j
        a[i], a[k] = a[k], a[i]
    return a


def insertion_sort(a):
    for i in range(1, len(a)):
        key = a[i]
        j = i - 1
        while j >= 0 and a[j] > key:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = key
    return a


def shell_sort(a):
    n = len(a)
    gap = n // 2
    while gap > 0:
        for i in range(gap, n):
            key = a[i]
            j = i
            while j >= gap and a[j - gap] > key:
                a[j] = a[j - gap]
                j -= gap
            a[j] = key
        gap //= 2
    return a


if __name__ == "__main__":
    import random
    sorts = {"冒泡": bubble_sort, "选择": selection_sort, "插入": insertion_sort, "希尔": shell_sort}
    for _ in range(300):
        arr = [random.randint(0, 60) for _ in range(random.randint(0, 100))]
        for name, fn in sorts.items():
            b = arr[:]
            fn(b)
            assert b == sorted(arr), (name, arr, b)
    print("冒泡/选择/插入/希尔 四排序正确性 OK（300 组随机）")
    # 插入排序在近乎有序时的比较次数演示
    arr = list(range(1000))
    arr[500], arr[501] = arr[501], arr[500]
    cmp_count = 0
    for i in range(1, len(arr)):
        key = arr[i]; j = i - 1
        while j >= 0 and arr[j] > key:
            cmp_count += 1
            arr[j + 1] = arr[j]; j -= 1
        arr[j + 1] = key
    print("近乎有序时插入排序比较次数（n=1000）:", cmp_count)
